#include <iostream>

using namespace std;

int main() {
    int h;
    unsigned long long n;
    cin >> h >> n;

    unsigned long long leafs = 1;
    for (int i = 0; i < h; ++i) {
        leafs *= 2;
    }

    unsigned long long side = leafs;
    unsigned long long residue = n;
    int i = 0;
    bool line = true;
    unsigned long long total = 0;

    while (i < h) {
        side /= 2;
        if (residue >= 2) {
            if (residue <= side) {
                if (line) {
                    line = !line;
                    total += 1;
                } else {
                    unsigned long long branch = 0;
                    unsigned long long k = 1;
                    for (int b = i; b < h; ++b) {
                        branch += k;
                        k *= 2;
                    }
                    total += branch + 1;
                }
            } else {
                residue -= side;
                if (!line) {
                    line = !line;
                    total += 1;
                } else {
                    unsigned long long branch = 0;
                    unsigned long long k = 1;
                    for (int b = i; b < h; ++b) {
                        branch += k;
                        k *= 2;
                    }
                    total += branch + 1;
                }
            }
        } else if (residue == 0) {
            if (!line) {
                line = !line;
                total += 1;
            } else {
                unsigned long long branch = 0;
                unsigned long long k = 1;
                for (int b = i; b < h; ++b) {
                    branch += k;
                    k *= 2;
                }
                total += branch + 1;
            }
        } else { // residue == 1
            if (line) {
                line = !line;
                total += 1;
            } else {
                unsigned long long branch = 0;
                unsigned long long k = 1;
                for (int b = i; b < h; ++b) {
                    branch += k;
                    k *= 2;
                }
                total += branch + 1;
            }
        }
        ++i;
    }

    cout << total << endl;
    return 0;
}

